import { normalize } from './normalize.mjs';

export function normalizeTags(values) {
  // Trim and lowercase each value using the existing helper
  const normalized = values.map(v => normalize(v));
  // Remove empty entries
  const nonEmpty = normalized.filter(v => v !== '');
  // Remove duplicates and sort alphabetically
  return [...new Set(nonEmpty)].sort();
}

export const tagLabel = value => normalize(value);

